// d_acsearch.cpp -- research D: bottleneck-ordered exhaustive search of the
// cyclic Andrews-Curtis graph on two-generator, two-relator presentations.
//
// Build:  g++ -O2 -std=c++17 -o d_acsearch experiments/d_acsearch.cpp
//
// STATES: unordered pairs of nonempty cyclically reduced words, modulo the
//   group Sigma generated by cyclic rotation of either relator, inversion of
//   either relator, and interchange of the relators.  Every element of Sigma
//   is a composite of ordinary AC moves (rotation = single-letter
//   conjugations, inversion = AC1, interchange = a fixed 9-move identity).
//   No automorphism of F(x,y) is used to identify states.
// MOVES ("cyclic products"): replace relator u by the cyclic reduction of
//   rot(u) * rot(v)^(+-1), v the other relator, for every pair of rotations
//   and both signs.  Each is a composite of ordinary AC moves (rotations,
//   at most two inversions of v, one right multiplication, cyclic reduction
//   by single-letter conjugations).  Mode --gs keeps only products in which
//   at least one letter cancels (the "GS substitution" graph of Fagan et al.
//   / Carreras); the default "full" mode also keeps cancellation-free
//   products.
// ENERGY: total length |r1|+|r2|.  BARRIER of a state: the minimum over
//   graph paths from a source of the maximum energy along the path.  States
//   are settled in nondecreasing barrier order (bucket queue), so after a
//   run with --cap C the settled set with barrier <= c is exactly the
//   connected component of the source(s) in the subgraph of energy <= c,
//   for every c <= C.
// DETECTION: a state is reported as TRIVIALIZING if one of its relators is
//   primitive in F(x,y) (Whitehead reduction to length 1).  For a balanced
//   presentation of the trivial group this implies AC-triviality (proof in
//   research/research-d.md, Lemma D1).  Target files (see below) are
//   matched exactly (Sigma) or up to the 8 length-preserving automorphisms
//   x<->y, x->x^-1, y->y^-1 (mode "aut8", only meaningful for targets that
//   are known AC-trivial: AC-triviality is Aut(F)-invariant, Lemma D2).
//
// Words use x,X,y,Y (capital = inverse).  Output is plain text.
#include <bits/stdc++.h>
using namespace std;
typedef uint64_t u64;
typedef uint32_t u32;
typedef uint8_t u8;

static const int MAXL = 31;  // max total length encodable in 64 bits
static inline u8 inv(u8 l) { return l ^ 1; }
static const char LET[4] = {'x', 'X', 'y', 'Y'};

static int letter_of(char c) {
  switch (c) {
    case 'x': return 0; case 'X': return 1; case 'y': return 2; case 'Y': return 3;
  }
  return -1;
}

// free + cyclic reduction in place; returns new length
static int reduce_cyc(u8* s, int n) {
  int m = 0;
  for (int i = 0; i < n; i++) {
    if (m && s[m - 1] == inv(s[i])) m--; else s[m++] = s[i];
  }
  int a = 0, b = m;
  while (b - a >= 2 && s[a] == inv(s[b - 1])) { a++; b--; }
  if (a) memmove(s, s + a, b - a);
  return b - a;
}

// least rotation start (two-pointer minimum expression), n >= 1
static int minrot(const u8* s, int n) {
  u8 d[2 * 64];
  memcpy(d, s, n); memcpy(d + n, s, n);
  int i = 0, j = 1, k = 0;
  while (i < n && j < n && k < n) {
    u8 a = d[i + k], b = d[j + k];
    if (a == b) { k++; continue; }
    if (a > b) i += k + 1; else j += k + 1;
    if (i == j) j++;
    k = 0;
  }
  return min(i, j);
}

// canonical representative under rotation and inversion
static void canon_word(const u8* s, int n, u8* out) {
  u8 t[64] = {0};
  for (int i = 0; i < n; i++) t[i] = inv(s[n - 1 - i]);
  int r1 = minrot(s, n), r2 = minrot(t, n);
  int c = 0;
  for (int i = 0; i < n; i++) {
    u8 a = s[(r1 + i) % n], b = t[(r2 + i) % n];
    if (a != b) { c = a < b ? -1 : 1; break; }
  }
  if (c <= 0) for (int i = 0; i < n; i++) out[i] = s[(r1 + i) % n];
  else for (int i = 0; i < n; i++) out[i] = t[(r2 + i) % n];
}

// order: shorter first, then lexicographic
static int cmpw(const u8* a, int na, const u8* b, int nb) {
  if (na != nb) return na < nb ? -1 : 1;
  for (int i = 0; i < na; i++) if (a[i] != b[i]) return a[i] < b[i] ? -1 : 1;
  return 0;
}

static u64 encode_ordered(const u8* a, int na, const u8* b, int nb) {
  u64 d = 0;
  auto push = [&](const u8* w, int n) {
    for (int i = 1; i < n; i++) {
      u8 c = w[i], f = inv(w[i - 1]);
      d = d * 3 + (u64)(c - (c > f ? 1 : 0));
    }
  };
  push(a, na); push(b, nb);
  u64 T = na + nb;
  return (T << 58) | ((u64)na << 53) | ((u64)a[0] << 51) | ((u64)b[0] << 49) | d;
}

// canonical key of a pair of canonical words
static u64 key_of_canon(const u8* a, int na, const u8* b, int nb) {
  if (cmpw(a, na, b, nb) <= 0) return encode_ordered(a, na, b, nb);
  return encode_ordered(b, nb, a, na);
}

static u64 key_of_pair(const u8* a, int na, const u8* b, int nb) {
  u8 ca[64], cb[64];
  canon_word(a, na, ca); canon_word(b, nb, cb);
  return key_of_canon(ca, na, cb, nb);
}

static void decode(u64 key, u8* a, int& na, u8* b, int& nb) {
  int T = (int)(key >> 58) & 31;
  na = (int)(key >> 53) & 31;
  nb = T - na;
  a[0] = (key >> 51) & 3; b[0] = (key >> 49) & 3;
  u64 d = key & ((1ULL << 49) - 1);
  int digits[64]; int nd = (na - 1) + (nb - 1);
  for (int i = nd - 1; i >= 0; i--) { digits[i] = (int)(d % 3); d /= 3; }
  int p = 0;
  auto pull = [&](u8* w, int n) {
    for (int i = 1; i < n; i++) {
      int dg = digits[p++]; u8 f = inv(w[i - 1]);
      u8 c = (u8)dg; if (c >= f) c++;
      w[i] = c;
    }
  };
  pull(a, na); pull(b, nb);
}

static string wstr(const u8* w, int n) { string s; for (int i = 0; i < n; i++) s += LET[w[i]]; return s; }
static string kstr(u64 key) {
  u8 a[64], b[64]; int na, nb; decode(key, a, na, b, nb);
  return wstr(a, na) + " " + wstr(b, nb);
}

// ---------- primitivity via Whitehead reduction (rank 2) ----------
// The four Whitehead automorphisms of F2 up to inner automorphisms:
// x->xy, x->xY, y->yx, y->yX.  Permutations do not change length.
static int apply_wh(const u8* s, int n, int which, u8* out) {
  // which: 0 x->xy, 1 x->xY, 2 y->yx, 3 y->yX
  u8 g = (which < 2) ? 0 : 2;          // generator being changed
  u8 h = (which < 2) ? 2 : 0;          // other generator
  u8 e = (which % 2 == 0) ? h : inv(h);  // multiplier
  int m = 0; u8 tmp[256];
  for (int i = 0; i < n; i++) {
    if (s[i] == g) { tmp[m++] = g; tmp[m++] = e; }
    else if (s[i] == inv(g)) { tmp[m++] = inv(e); tmp[m++] = inv(g); }
    else tmp[m++] = s[i];
  }
  if (m > 120) return -1;
  int L = reduce_cyc(tmp, m);
  memcpy(out, tmp, L);
  return L;
}

static bool is_primitive_impl(const u8* s0, int n0, bool filter) {
  if (n0 == 1) return true;
  bool has[4] = {false, false, false, false};
  for (int i = 0; i < n0; i++) has[s0[i]] = true;
  // classical necessary condition (cyclically reduced primitive words of F2
  // use each generator with one sign); also checked exhaustively to length 12
  // in --self-test
  if (filter && ((has[0] && has[1]) || (has[2] && has[3]))) return false;
  u8 s[128]; int n = n0; memcpy(s, s0, n);
  while (true) {
    if (n == 1) return true;
    bool improved = false;
    for (int w = 0; w < 4 && !improved; w++) {
      u8 t[128]; int L = apply_wh(s, n, w, t);
      if (L >= 0 && L < n) { memcpy(s, t, L); n = L; improved = true; }
    }
    if (!improved) return false;  // Whitehead: minimal length > 1, not primitive
  }
}
static bool is_primitive(const u8* s0, int n0) { return is_primitive_impl(s0, n0, true); }

// ---------- hash set of keys -> index ----------
struct Table {
  vector<u32> slot; u64 mask; const vector<u64>* keys;
  void init(int logsize, const vector<u64>* k) { slot.assign(1ULL << logsize, 0); mask = (1ULL << logsize) - 1; keys = k; }
  static inline u64 h(u64 x) { x += 0x9e3779b97f4a7c15ULL; x = (x ^ (x >> 30)) * 0xbf58476d1ce4e5b9ULL; x = (x ^ (x >> 27)) * 0x94d049bb133111ebULL; return x ^ (x >> 31); }
  // returns index or -1; if insert_idx>=0 and absent, inserts
  inline long long find_or_insert(u64 key, long long insert_idx) {
    u64 p = h(key) & mask;
    while (true) {
      u32 v = slot[p];
      if (!v) { if (insert_idx >= 0) slot[p] = (u32)(insert_idx + 1); return -1; }
      if ((*keys)[v - 1] == key) return v - 1;
      p = (p + 1) & mask;
    }
  }
};

struct Target { string id; int kind; };  // kind 0 exact, 1 aut8-trivial

// ---------- Aut(F2)-orbit canonical form of a pair (Whitehead) ----------
// Minimize total cyclic length with the 4 rank-2 Whitehead maps (x->xy,
// x->xY, y->yx, y->yX act on conjugacy classes like all type-II Whitehead
// automorphisms up to inner ones).  By Whitehead's theorem for tuples of
// cyclic words, a tuple not of minimal length in its Aut-orbit is shortened
// by one of them, and (peak reduction) all minimal tuples of the orbit are
// D8 x (closure of one minimal tuple under these maps at constant length),
// D8 = the 8 signed permutations.  The canonical key is the minimum Sigma-key
// over that set.  Returns false if the closure exceeds `limit` elements.
static u8 d8img(u8 l, int g) {
  u8 base = l & 2, sgn = l & 1;
  if (g & 1) base ^= 2;
  if ((base == 0 && (g & 2)) || (base == 2 && (g & 4))) sgn ^= 1;
  return (u8)(base | sgn);
}
static bool aut_canon(const u8* a0, int na0, const u8* b0, int nb0, u64& out, int& minlen, size_t limit = 20000) {
  u8 a[128], b[128]; int na = na0, nb = nb0; memcpy(a, a0, na); memcpy(b, b0, nb);
  while (true) {
    bool imp = false;
    for (int m = 0; m < 4 && !imp; m++) {
      u8 ta[128], tb[128]; int la = apply_wh(a, na, m, ta), lb = apply_wh(b, nb, m, tb);
      if (la > 0 && lb > 0 && la + lb < na + nb) { memcpy(a, ta, la); na = la; memcpy(b, tb, lb); nb = lb; imp = true; }
    }
    if (!imp) break;
  }
  minlen = na + nb;
  if (minlen > MAXL) return false;
  // closure at constant length
  vector<u64> stack; unordered_set<u64> seen;
  u64 k0 = key_of_pair(a, na, b, nb); stack.push_back(k0); seen.insert(k0);
  while (!stack.empty()) {
    u64 k = stack.back(); stack.pop_back();
    u8 x[64], y[64]; int nx, ny; decode(k, x, nx, y, ny);
    for (int m = 0; m < 4; m++) {
      u8 tx[128], ty[128]; int lx = apply_wh(x, nx, m, tx), ly = apply_wh(y, ny, m, ty);
      if (lx > 0 && ly > 0 && lx + ly == minlen) {
        u64 kk = key_of_pair(tx, lx, ty, ly);
        if (seen.insert(kk).second) { stack.push_back(kk); if (seen.size() > limit) return false; }
      } else if (lx > 0 && ly > 0 && lx + ly < minlen) {
        fprintf(stderr, "internal error: Whitehead minimization not minimal\n"); exit(3);
      }
    }
  }
  u64 best = ~0ULL;
  for (u64 k : seen) {
    u8 x[64], y[64]; int nx, ny; decode(k, x, nx, y, ny);
    for (int g = 0; g < 8; g++) {
      u8 gx[64], gy[64];
      for (int t = 0; t < nx; t++) gx[t] = d8img(x[t], g);
      for (int t = 0; t < ny; t++) gy[t] = d8img(y[t], g);
      best = min(best, key_of_pair(gx, nx, gy, ny));
    }
  }
  out = best; return true;
}

// --autmatch KEYFILE TARGETFILE...: Aut-canonicalize every state in KEYFILE
// (binary u64 Sigma-keys written by --dumpkeys) and every target presentation,
// report histogram of Aut-minimal lengths and all matches.
static int aut_match(int argc, char** argv) {
  string keyfile = argv[2];
  string autdump; int first_target = 3;
  if (argc >= 5 && string(argv[3]) == "--autdump") { autdump = argv[4]; first_target = 5; }
  FILE* adf = autdump.empty() ? nullptr : fopen(autdump.c_str(), "wb");
  vector<pair<u64, u32>> tv; vector<string> tid;
  long long tfail = 0;
  for (int f = first_target; f < argc; f++) {
    ifstream in(argv[f]); string line; long long n = 0;
    while (getline(in, line)) {
      istringstream ss(line); string id, w1, w2; ss >> id >> w1 >> w2;
      u8 a[128], b[128]; int na = 0, nb = 0; bool ok = true;
      for (char c : w1) { int l = letter_of(c); if (l < 0 || na >= 120) { ok = false; break; } a[na++] = l; }
      for (char c : w2) { int l = letter_of(c); if (l < 0 || nb >= 120) { ok = false; break; } b[nb++] = l; }
      if (!ok) { tfail++; continue; }
      na = reduce_cyc(a, na); nb = reduce_cyc(b, nb);
      if (!na || !nb) { tfail++; continue; }
      // reduce first if too long to encode
      u64 k; int ml;
      if (na + nb > MAXL) {  // Whitehead-reduce without encoding
        bool imp = true;
        while (imp && na + nb > MAXL) { imp = false;
          for (int m = 0; m < 4 && !imp; m++) { u8 ta[128], tb[128]; int la = apply_wh(a, na, m, ta), lb = apply_wh(b, nb, m, tb);
            if (la > 0 && lb > 0 && la + lb < na + nb) { memcpy(a, ta, la); na = la; memcpy(b, tb, lb); nb = lb; imp = true; } } }
        if (na + nb > MAXL) { tfail++; continue; }
      }
      if (!aut_canon(a, na, b, nb, k, ml)) { tfail++; continue; }
      tv.push_back({k, (u32)tid.size()}); tid.push_back(id); n++;
    }
    fprintf(stderr, "aut targets %s: %lld canonicalized\n", argv[f], n);
  }
  sort(tv.begin(), tv.end());
  FILE* kf = fopen(keyfile.c_str(), "rb"); if (!kf) { fprintf(stderr, "cannot open %s\n", keyfile.c_str()); return 2; }
  vector<long long> hist(64, 0); long long n = 0, fails = 0, hits = 0; int global_min = 99;
  map<u64, u64> shortorb; map<u64, long long> shortcount;
  u64 buf[4096]; size_t got;
  while ((got = fread(buf, 8, 4096, kf)) > 0) {
    for (size_t i = 0; i < got; i++) {
      u8 a[64], b[64]; int na, nb; decode(buf[i], a, na, b, nb);
      u64 k; int ml; n++;
      if (!aut_canon(a, na, b, nb, k, ml)) { fails++; continue; }
      hist[ml]++; global_min = min(global_min, ml);
      if (adf) fwrite(&k, 8, 1, adf);
      if (ml <= 14) { auto r = shortorb.insert({k, buf[i]}); (void)r; shortcount[k]++; }
      auto it = lower_bound(tv.begin(), tv.end(), make_pair(k, (u32)0));
      for (; it != tv.end() && it->first == k; ++it) { hits++; if (hits <= 50) printf("AUTHIT state [%s] target %s\n", kstr(buf[i]).c_str(), tid[it->second].c_str()); }
    }
  }
  fclose(kf); if (adf) fclose(adf);
  printf("autmatch states %lld closure_fail %lld targets %zu target_fail %lld hits %lld min_aut_length %d\n", n, fails, tv.size(), tfail, hits, global_min);
  for (int L = 0; L < 64; L++) if (hist[L]) printf("aut_min_length %d states %lld\n", L, hist[L]);
  for (auto& o : shortorb) printf("AUTORBIT len %d canon [%s] states_in_component %lld example [%s]\n", (int)((o.first >> 58) & 31), kstr(o.first).c_str(), shortcount[o.first], kstr(o.second).c_str());
  return 0;
}

// ---------- self-test ----------
static int self_test() {
  mt19937_64 rng(12345);
  auto rand_word = [&](int n, u8* w) {
    while (true) {
      for (int i = 0; i < n; i++) { do { w[i] = rng() & 3; } while (i && w[i] == inv(w[i - 1])); }
      if (n < 2 || w[0] != inv(w[n - 1])) return;
    }
  };
  for (int it = 0; it < 200000; it++) {
    int na = 1 + rng() % 15, nb = 1 + rng() % 15;
    u8 a[64], b[64]; rand_word(na, a); rand_word(nb, b);
    u64 k = key_of_pair(a, na, b, nb);
    // round trip
    u8 c[64], d[64]; int nc, nd; decode(k, c, nc, d, nd);
    if (key_of_pair(c, nc, d, nd) != k) { printf("FAIL roundtrip\n"); return 1; }
    // Sigma invariance: rotate a, invert b, swap
    int r = rng() % na; u8 a2[64], b2[64];
    for (int i = 0; i < na; i++) a2[i] = a[(i + r) % na];
    for (int i = 0; i < nb; i++) b2[i] = inv(b[nb - 1 - i]);
    if (key_of_pair(b2, nb, a2, na) != k) { printf("FAIL sigma invariance\n"); return 1; }
  }
  auto parse = [](const char* s, u8* w) { int n = 0; for (; *s; s++) w[n++] = letter_of(*s); return n; };
  const char* prim[] = {"x", "Y", "xy", "xxy", "xyxyy", "xxyxxyxy", "YXYYXYYX", "xyxyxyy"};
  const char* nonprim[] = {"xxyy", "xxxyy", "xyXY", "xyxYXY", "xxxYYYY", "xx", "xyyxY"};
  for (auto s : prim) { u8 w[64]; int n = parse(s, w); if (!is_primitive(w, n)) { printf("FAIL primitive %s\n", s); return 1; } }
  for (auto s : nonprim) { u8 w[64]; int n = parse(s, w); if (is_primitive(w, n)) { printf("FAIL nonprimitive %s\n", s); return 1; } }
  {
    // aut_canon: AK(3) and its image under x->xy must agree; trivial pair -> length 2
    u8 a[64], b[64], c[64], d[64]; int na = parse("xxxYYYY", a), nb = parse("xyxYXY", b);
    u64 k1, k2; int m1, m2; aut_canon(a, na, b, nb, k1, m1);
    int nc = apply_wh(a, na, 0, c), nd = apply_wh(b, nb, 0, d);
    aut_canon(c, nc, d, nd, k2, m2);
    if (k1 != k2 || m1 != 13) { printf("FAIL aut_canon AK3 %d %d\n", m1, m2); return 1; }
    nc = parse("x", c); nd = parse("y", d);
    for (int m : {0, 2, 0, 3, 1, 2}) { u8 t1[128], t2[128]; int l1 = apply_wh(c, nc, m, t1), l2 = apply_wh(d, nd, m, t2); memcpy(c, t1, l1); nc = l1; memcpy(d, t2, l2); nd = l2; }
    aut_canon(c, nc, d, nd, k2, m2);
    if (m2 != 2) { printf("FAIL aut_canon trivial %d\n", m2); return 1; }
  }
  {
    // exhaustive check of the primitivity filter on all cyclically reduced words of length <= 12
    long long nw = 0, nprim = 0;
    for (int n = 1; n <= 12; n++) {
      u8 w[64]; int d[64];
      // enumerate via odometer over first letter (4) and n-1 digits (3)
      long long total = 4; for (int i = 1; i < n; i++) total *= 3;
      for (long long c = 0; c < total; c++) {
        long long t = c; w[0] = t % 4; t /= 4;
        for (int i = 1; i < n; i++) { d[i] = t % 3; t /= 3; u8 f = inv(w[i - 1]); u8 l = (u8)d[i]; if (l >= f) l++; w[i] = l; }
        if (n >= 2 && w[0] == inv(w[n - 1])) continue;
        nw++;
        bool a = is_primitive_impl(w, n, false), b = is_primitive_impl(w, n, true);
        if (a != b) { printf("FAIL primitivity filter on %s\n", wstr(w, n).c_str()); return 1; }
        nprim += a;
      }
    }
    printf("primitivity filter agrees with unfiltered Whitehead on all %lld cyclically reduced words of length <= 12 (%lld primitive)\n", nw, nprim);
  }
  int autchecks = 0;
  for (int it = 0; it < 3000; it++) {
    int na = 1 + rng() % 8, nb = 1 + rng() % 8;
    u8 a[128], b[128]; rand_word(na, a); rand_word(nb, b);
    u64 k1; int m1; if (!aut_canon(a, na, b, nb, k1, m1)) continue;
    u8 c[128], d[128]; int nc = na, nd = nb; memcpy(c, a, na); memcpy(d, b, nb);
    int g = rng() % 8; for (int t = 0; t < nc; t++) c[t] = d8img(c[t], g); for (int t = 0; t < nd; t++) d[t] = d8img(d[t], g);
    bool ok = true;
    for (int r = 0; r < 3; r++) { int m = rng() % 4; u8 t1[128], t2[128]; int l1 = apply_wh(c, nc, m, t1), l2 = apply_wh(d, nd, m, t2);
      if (l1 <= 0 || l2 <= 0 || l1 + l2 > MAXL) { ok = false; break; } memcpy(c, t1, l1); nc = l1; memcpy(d, t2, l2); nd = l2; }
    if (!ok) continue;
    u64 k2; int m2; if (!aut_canon(c, nc, d, nd, k2, m2)) continue;
    if (k1 != k2 || m1 != m2) { printf("FAIL aut invariance [%s] vs [%s]\n", kstr(key_of_pair(a,na,b,nb)).c_str(), kstr(key_of_pair(c,nc,d,nd)).c_str()); return 1; }
    autchecks++;
  }
  printf("aut-canonical invariance checks passed: %d\n", autchecks);
  printf("self-test passed: 200000 random encode/decode + Sigma-invariance checks, %d primitivity checks\n", 15);
  return 0;
}

int main(int argc, char** argv) {
  if (argc == 2 && string(argv[1]) == "--self-test") return self_test();
  if (argc >= 3 && string(argv[1]) == "--autmatch") return aut_match(argc, argv);
  if (argc == 4 && string(argv[1]) == "--autcompare") {
    vector<u64> A[2];
    for (int t = 0; t < 2; t++) { FILE* f = fopen(argv[2 + t], "rb"); if (!f) return 2; u64 buf[4096]; size_t got;
      while ((got = fread(buf, 8, 4096, f)) > 0) A[t].insert(A[t].end(), buf, buf + got); fclose(f);
      sort(A[t].begin(), A[t].end()); A[t].erase(unique(A[t].begin(), A[t].end()), A[t].end()); }
    vector<u64> I; set_intersection(A[0].begin(), A[0].end(), A[1].begin(), A[1].end(), back_inserter(I));
    printf("autcompare distinct_orbits %zu %zu common %zu\n", A[0].size(), A[1].size(), I.size());
    for (size_t i = 0; i < I.size() && i < 20; i++) printf("COMMON [%s]\n", kstr(I[i]).c_str());
    return 0;
  }
  int cap = 25; bool gs = false; long long maxstates = 50000000; int logtable = 0;
  vector<pair<string, string>> sources;
  vector<pair<string, int>> target_files;
  string dumpfile; int dumpmax = -1; string dumpkeysfile; int dumpkeys_src = -1; string tkeyfile; int maxhits_print = 50; bool stop_on_trivial = true;
  for (int i = 1; i < argc; i++) {
    string a = argv[i];
    auto next = [&]() { if (i + 1 >= argc) { fprintf(stderr, "missing arg for %s\n", a.c_str()); exit(2); } return string(argv[++i]); };
    if (a == "--cap") cap = stoi(next());
    else if (a == "--gs") gs = true;
    else if (a == "--maxstates") maxstates = stoll(next());
    else if (a == "--logtable") logtable = stoi(next());
    else if (a == "--source") { string s = next(); size_t c = s.find(','); sources.push_back({s.substr(0, c), s.substr(c + 1)}); }
    else if (a == "--exact-targets") target_files.push_back({next(), 0});
    else if (a == "--trivial-targets") target_files.push_back({next(), 1});
    else if (a == "--dump") { dumpmax = stoi(next()); dumpfile = next(); }
    else if (a == "--target-keys") tkeyfile = next();
    else if (a == "--dumpkeys") { dumpkeys_src = stoi(next()); dumpkeysfile = next(); }
    else if (a == "--maxhits") maxhits_print = stoi(next());
    else if (a == "--no-stop") stop_on_trivial = false;
    else { fprintf(stderr, "unknown option %s\n", a.c_str()); return 2; }
  }
  if (cap > MAXL) { fprintf(stderr, "cap must be <= %d\n", MAXL); return 2; }
  if (sources.empty()) sources.push_back({"xxxYYYY", "xyxYXY"});  // AK(3)
  if (!logtable) { logtable = 20; while ((1ULL << logtable) < (u64)(maxstates * 1.6)) logtable++; }

  vector<u64> keys; vector<u32> parent; vector<u8> barrier, src;
  keys.reserve(maxstates + 64); parent.reserve(maxstates + 64); barrier.reserve(maxstates + 64); src.reserve(maxstates + 64);
  Table T; T.init(logtable, &keys);

  // targets: map key -> list of target indices
  vector<Target> targets; vector<pair<u64, u32>> tvec;
  for (auto& tf : target_files) {
    ifstream in(tf.first); if (!in) { fprintf(stderr, "cannot open %s\n", tf.first.c_str()); return 2; }
    string line; long long nread = 0, nused = 0;
    while (getline(in, line)) {
      if (line.empty() || line[0] == '#') continue;
      nread++;
      istringstream ss(line); string id, w1, w2; ss >> id >> w1 >> w2;
      u8 a[128], b[128]; int na = 0, nb = 0; bool ok = true;
      for (char c : w1) { int l = letter_of(c); if (l < 0 || na >= 120) { ok = false; break; } a[na++] = l; }
      for (char c : w2) { int l = letter_of(c); if (l < 0 || nb >= 120) { ok = false; break; } b[nb++] = l; }
      if (!ok) continue;
      na = reduce_cyc(a, na); nb = reduce_cyc(b, nb);
      if (!na || !nb || na + nb > cap) continue;
      int tidx = targets.size(); targets.push_back({id, tf.second}); nused++;
      int nimg = tf.second == 1 ? 8 : 1;
      set<u64> seen;
      for (int g = 0; g < nimg; g++) {
        // g bit0: swap x<->y, bit1: invert x, bit2: invert y
        u8 ia[128], ib[128];
        auto img = [&](u8 l) { u8 base = l & 2, sgn = l & 1; if (g & 1) base ^= 2; if ((base == 0 && (g & 2)) || (base == 2 && (g & 4))) sgn ^= 1; return (u8)(base | sgn); };
        for (int t = 0; t < na; t++) ia[t] = img(a[t]);
        for (int t = 0; t < nb; t++) ib[t] = img(b[t]);
        u64 k = key_of_pair(ia, na, ib, nb);
        if (seen.insert(k).second) tvec.push_back({k, (u32)tidx});
      }
    }
    fprintf(stderr, "targets %s: read %lld, usable(<=cap) %lld\n", tf.first.c_str(), nread, nused);
  }
  sort(tvec.begin(), tvec.end());
  vector<u64> tkeys;  // exact Sigma-keys of a previously dumped component
  if (!tkeyfile.empty()) {
    FILE* f = fopen(tkeyfile.c_str(), "rb"); if (!f) { fprintf(stderr, "cannot open %s\n", tkeyfile.c_str()); return 2; }
    u64 buf[4096]; size_t got; while ((got = fread(buf, 8, 4096, f)) > 0) tkeys.insert(tkeys.end(), buf, buf + got);
    fclose(f); sort(tkeys.begin(), tkeys.end());
    fprintf(stderr, "target keys %s: %zu\n", tkeyfile.c_str(), tkeys.size());
  }
  vector<long long> tkey_hits;

  vector<vector<u32>> bucket(cap + 2);
  long long hits_found = 0; vector<pair<long long, int>> hits;  // state idx, target idx
  vector<long long> trivial_states;
  // collisions between sources
  map<pair<int, int>, tuple<int, u32, u32>> collide;

  auto add_state = [&](u64 key, int bar, long long par, int s) -> long long {
    long long idx = keys.size();
    long long f = T.find_or_insert(key, idx);
    if (f >= 0) return -(f + 1) - 1;  // existing: return -(idx)-2
    keys.push_back(key); parent.push_back(par < 0 ? 0xFFFFFFFFu : (u32)par);
    barrier.push_back((u8)bar); src.push_back((u8)s);
    bucket[bar].push_back((u32)idx);
    // detection
    u8 a[64], b[64]; int na, nb; decode(key, a, na, b, nb);
    if (is_primitive(a, na) || is_primitive(b, nb)) trivial_states.push_back(idx);
    auto it = lower_bound(tvec.begin(), tvec.end(), make_pair(key, (u32)0));
    for (; it != tvec.end() && it->first == key; ++it) hits.push_back({idx, (int)it->second});
    if (!tkeys.empty() && binary_search(tkeys.begin(), tkeys.end(), key)) tkey_hits.push_back(idx);
    return idx;
  };

  for (size_t s = 0; s < sources.size(); s++) {
    u8 a[128], b[128]; int na = 0, nb = 0;
    for (char c : sources[s].first) a[na++] = letter_of(c);
    for (char c : sources[s].second) b[nb++] = letter_of(c);
    na = reduce_cyc(a, na); nb = reduce_cyc(b, nb);
    u64 k = key_of_pair(a, na, b, nb);
    long long r = add_state(k, na + nb, -1, (int)s);
    if (r < 0) fprintf(stderr, "source %zu duplicates an earlier source\n", s);
    fprintf(stderr, "source %zu: %s (energy %d)\n", s, kstr(k).c_str(), na + nb);
  }

  long long expanded = 0; bool budget_hit = false; int last_full_barrier = -1;
  auto t0 = chrono::steady_clock::now();
  for (int b = 0; b <= cap && !budget_hit; b++) {
    for (size_t qi = 0; qi < bucket[b].size(); qi++) {
      u32 cur = bucket[b][qi];
      u8 A[64], B[64]; int na, nb; decode(keys[cur], A, na, B, nb);
      int s = src[cur];
      expanded++;
      for (int side = 0; side < 2; side++) {
        const u8* U = side ? B : A; int nu = side ? nb : na;
        const u8* V0 = side ? A : B; int nv = side ? na : nb;  // canonical donor, unchanged
        if (nu + nv + nv - 0 > cap + 2 * min(nu, nv) + 2) {}  // (no cheap global prune)
        u8 UU[128]; memcpy(UU, U, nu); memcpy(UU + nu, U, nu);
        for (int sg = 0; sg < 2; sg++) {
          u8 V[64];
          if (sg == 0) memcpy(V, V0, nv); else for (int t = 0; t < nv; t++) V[t] = inv(V0[nv - 1 - t]);
          u8 VV[128]; memcpy(VV, V, nv); memcpy(VV + nv, V, nv);
          for (int k = 0; k < nu; k++) {
            const u8* Ur = UU + k;
            for (int l = 0; l < nv; l++) {
              const u8* Vr = VV + l;
              int c1 = 0;
              int mn = min(nu, nv);
              while (c1 < mn && Ur[nu - 1 - c1] == inv(Vr[c1])) c1++;
              u8 Wd[128]; int L;
              if (c1 < mn) {
                if (Vr[nv - 1] == inv(Ur[0])) continue;  // represented by a shifted alignment
                L = nu + nv - 2 * c1;
                if (gs && c1 == 0) continue;
                if (L + nv > cap) continue;
                int m = 0;
                for (int t = 0; t < nu - c1; t++) Wd[m++] = Ur[t];
                for (int t = c1; t < nv; t++) Wd[m++] = Vr[t];
              } else {
                int m = 0;
                for (int t = 0; t < nu; t++) Wd[m++] = Ur[t];
                for (int t = 0; t < nv; t++) Wd[m++] = Vr[t];
                L = reduce_cyc(Wd, m);
                if (L == 0 || L + nv > cap) continue;
              }
              int e = L + nv;
              u8 Wc[64]; canon_word(Wd, L, Wc);
              u64 key = key_of_canon(Wc, L, V0, nv);
              int nbar = max(b, e);
              long long r = add_state(key, nbar, cur, s);
              if (r < -1) {
                long long other = -r - 2;
                if (src[other] != s) {
                  int cb = max(b, (int)barrier[other]);
                  auto pr = make_pair(min(s, (int)src[other]), max(s, (int)src[other]));
                  auto it = collide.find(pr);
                  if (it == collide.end() || get<0>(it->second) > cb) collide[pr] = make_tuple(cb, cur, (u32)other);
                }
              }
              if ((long long)keys.size() >= maxstates) budget_hit = true;
            }
          }
        }
      }
      if (budget_hit) break;
      if (stop_on_trivial && !trivial_states.empty()) { budget_hit = true; break; }
    }
    if (!budget_hit) last_full_barrier = b;
    double el = chrono::duration<double>(chrono::steady_clock::now() - t0).count();
    if (b >= 13 || !bucket[b].empty())
      fprintf(stderr, "barrier %d done=%d: settled-so-far %zu, expanded %lld, %.1fs\n", b, !budget_hit, keys.size(), expanded, el);
  }

  // ---------- report ----------
  printf("mode %s cap %d sources %zu\n", gs ? "GS(cancelling products)" : "FULL(all cyclic products)", cap, sources.size());
  for (size_t s = 0; s < sources.size(); s++) printf("source %zu %s %s\n", s, sources[s].first.c_str(), sources[s].second.c_str());
  printf("budget_hit %d last_complete_barrier %d total_states %zu expanded %lld\n", (int)budget_hit, last_full_barrier, keys.size(), expanded);
  // counts by barrier and source (complete only up to last_full_barrier)
  vector<vector<long long>> cnt(sources.size(), vector<long long>(cap + 2, 0)), ecnt(sources.size(), vector<long long>(cap + 2, 0));
  for (size_t i = 0; i < keys.size(); i++) { cnt[src[i]][barrier[i]]++; if (barrier[i] <= last_full_barrier) ecnt[src[i]][(keys[i] >> 58) & 31]++; }
  for (size_t s = 0; s < sources.size(); s++) {
    long long cum = 0;
    for (int b = 0; b <= cap; b++) { cum += cnt[s][b]; if (cnt[s][b]) printf("src %zu barrier %d new %lld cumulative %lld%s\n", s, b, cnt[s][b], cum, b <= last_full_barrier ? "" : " (incomplete)"); }
    for (int e = 0; e <= cap; e++) if (ecnt[s][e]) printf("src %zu energy %d states %lld (within complete barrier<=%d)\n", s, e, ecnt[s][e], last_full_barrier);
  }
  for (auto& c : collide) printf("collision src %d-%d min_barrier_found %d\n", c.first.first, c.first.second, get<0>(c.second));
  auto path_to = [&](long long idx) {
    vector<long long> p; while (idx >= 0) { p.push_back(idx); u32 q = parent[idx]; idx = (q == 0xFFFFFFFFu) ? -1 : (long long)q; }
    reverse(p.begin(), p.end()); return p;
  };
  auto print_path = [&](const char* tag, long long idx) {
    auto p = path_to(idx);
    printf("PATH %s len %zu :", tag, p.size());
    for (auto q : p) printf(" [%s]", kstr(keys[q]).c_str());
    printf("\n");
  };
  printf("trivializing_states %zu\n", trivial_states.size());
  for (size_t i = 0; i < trivial_states.size() && (int)i < maxhits_print; i++) print_path("TRIVIAL", trivial_states[i]);
  printf("target_key_hits %zu\n", tkey_hits.size());
  { int mb = 99; long long bi = -1; for (auto q : tkey_hits) if (barrier[q] < mb) { mb = barrier[q]; bi = q; }
    if (bi >= 0) { printf("TKEYHIT min_barrier %d state [%s]\n", mb, kstr(keys[bi]).c_str()); print_path("TKEYHIT", bi); } }
  printf("target_hits %zu\n", hits.size());
  for (size_t i = 0; i < hits.size(); i++) {
    auto& h = hits[i];
    printf("HIT target %s kind %s state [%s] barrier %d src %d\n", targets[h.second].id.c_str(), targets[h.second].kind ? "aut8-trivial" : "exact", kstr(keys[h.first]).c_str(), (int)barrier[h.first], (int)src[h.first]);
    if ((int)i < maxhits_print) print_path(targets[h.second].id.c_str(), h.first);
  }
  for (auto& c : collide) {
    printf("COLLISION %d-%d barrier %d\n", c.first.first, c.first.second, get<0>(c.second));
    print_path("COLL_A", get<1>(c.second)); print_path("COLL_B", get<2>(c.second));
  }
  if (dumpkeys_src >= 0) {
    FILE* f = fopen(dumpkeysfile.c_str(), "wb"); long long nk = 0;
    for (size_t i = 0; i < keys.size(); i++) if ((dumpkeys_src == 99 || src[i] == dumpkeys_src) && barrier[i] <= last_full_barrier) { fwrite(&keys[i], 8, 1, f); nk++; }
    fclose(f); printf("dumped %lld keys of source %d to %s\n", nk, dumpkeys_src, dumpkeysfile.c_str());
  }
  if (dumpmax >= 0) {
    FILE* f = fopen(dumpfile.c_str(), "w");
    for (size_t i = 0; i < keys.size(); i++) if ((int)((keys[i] >> 58) & 31) <= dumpmax && barrier[i] <= last_full_barrier)
      fprintf(f, "%s %d %d %d\n", kstr(keys[i]).c_str(), (int)((keys[i] >> 58) & 31), (int)barrier[i], (int)src[i]);
    fclose(f);
  }
  return 0;
}
